using System.Text.Json;
using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Environment = "Production",
            MaxConnections = 100,
            FeatureFlags = new { DarkMode = true, BetaFeatures = false },
            ApiVersion = "v2"
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/endpoints", Name = "Service Endpoints",
        MimeType = "application/json"),
     Description("Returns configured service endpoint URLs.")]
    public static string GetEndpoints()
    {
        var endpoints = new
        {
            Database = "postgres://db.internal:5432/app",
            Cache = "redis://cache.internal:6379",
            Queue = "amqp://mq.internal:5672"
        };

        return JsonSerializer.Serialize(endpoints, new JsonSerializerOptions { WriteIndented = true });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Check if a specific feature flag is enabled.")]
    public static string CheckFeatureFlag(
        [Description("Name of the feature flag to check")] string flagName)
    {
        var flags = new Dictionary<string, bool>
        {
            ["DarkMode"] = true,
            ["BetaFeatures"] = false,
            ["Notifications"] = true
        };

        if (flags.TryGetValue(flagName, out var enabled))
            return $"Feature '{flagName}' is {(enabled ? "enabled" : "disabled")}.";

        return $"Feature '{flagName}' not found. Available: {string.Join(", ", flags.Keys)}";
    }
}

